import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

M = 4096

tril_mm_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void tril_mm_kernel(const float* A, const float* B, float* C, int N) {
    int row = blockIdx.x * blockDim.x + threadIdx.x;
    int col = blockIdx.y * blockDim.y + threadIdx.y;
    if (row < N && col < N) {
        float val = 0.0f;
        // Only compute lower-triangular part
        if (row >= col) {
            int end = (row < col ? row : col);
            for (int k = 0; k <= end; k++) {
                val += A[row * N + k] * B[k * N + col];
            }
        }
        C[row * N + col] = val;
    }
}

torch::Tensor tril_mm_cuda(torch::Tensor A, torch::Tensor B) {
    TORCH_CHECK(A.dim() == 2 && B.dim() == 2, "Expected 2D tensors");
    TORCH_CHECK(A.size(0) == A.size(1) && B.size(0) == B.size(1), "Matrices must be square");
    TORCH_CHECK(A.size(0) == B.size(0), "Dimension mismatch");
    int N = A.size(0);

    auto C = torch::zeros_like(A);

    const int BLOCK_SIZE = 16;
    dim3 threads(BLOCK_SIZE, BLOCK_SIZE);
    dim3 blocks((N + BLOCK_SIZE - 1) / BLOCK_SIZE, (N + BLOCK_SIZE - 1) / BLOCK_SIZE);

    tril_mm_kernel<<<blocks, threads>>>(A.data_ptr<float>(), B.data_ptr<float>(), C.data_ptr<float>(), N);

    return C;
}
"""

tril_mm_cpp_source = "torch::Tensor tril_mm_cuda(torch::Tensor A, torch::Tensor B);"

mm_extension = load_inline(
    name="tril_mm_extension",
    cpp_sources=tril_mm_cpp_source,
    cuda_sources=tril_mm_source,
    functions=["tril_mm_cuda"],
    verbose=False,
    extra_cflags=["-O3"],
    extra_ldflags=[]
)

class ModelNew(nn.Module):
    def __init__(self):
        super(ModelNew, self).__init__()

    def forward(self, A, B):
        return mm_extension.tril_mm_cuda(A, B)

def get_inputs():
    A = torch.randn(M, M)
    B = torch.randn(M, M)
    A = torch.tril(A)
    B = torch.tril(B)
    return [A, B]

def get_init_inputs():
    return []
